components.css:
.ds-primary{min-height:44px;border-radius:6px;padding:10px 16px;font-size:13px;font-weight:600;border:1px solid transparent;cursor:pointer;transition:background 140ms,border-color 140ms;background: var(--accent, #2459bb);
  border-color: var(--accent, #2459bb);
  color: white;}.ds-primary:hover:not(:disabled){background: #194797;
  border-color: #194797;}.ds-primary:focus-visible { outline:2px solid var(--accent, #2459bb);outline-offset:3px; }.ds-primary:disabled{opacity:.55;cursor:not-allowed} @media(prefers-reduced-motion:reduce){[class^="ds-"]{transition:none !important}}

.ds-secondary{min-height:44px;border-radius:6px;padding:10px 16px;font-size:13px;font-weight:600;border:1px solid transparent;cursor:pointer;transition:background 140ms,border-color 140ms;min-height: 44px;
  border-radius: 6px;
  padding: 10px 16px;
  font-size: 13px;
  font-weight: 600;
  border: 1px solid transparent;
  white-space: nowrap;}.ds-secondary:hover:not(:disabled){background: #f3f6fa;
  border-color: #8c9eb7;}.ds-secondary:focus-visible { outline:2px solid var(--accent, #2459bb);outline-offset:3px; }.ds-secondary:disabled{opacity:.55;cursor:not-allowed} @media(prefers-reduced-motion:reduce){[class^="ds-"]{transition:none !important}}

.ds-text{min-height: 44px;
  color: var(--accent, #2459bb);
  background: transparent;
  border: 0;
  font-size: 13px;
  font-weight: 550;
  padding: 8px;}.ds-text:hover{text-decoration:underline}.ds-text:focus-visible { outline:2px solid var(--accent, #2459bb);outline-offset:3px; } @media(prefers-reduced-motion:reduce){[class^="ds-"]{transition:none !important}}

.ds-field{display: block;
  font-size: 13px;
  font-weight: 600;
  color: #35445c;}.ds-field textarea{display:block;width:100%;margin-top:8px;padding:12px 14px;color:var(--text,#202a3b);background:var(--surface,#fff);border:1px solid #b7c4d5;border-radius:6px;font-size:14px;font-weight:400;min-height:260px;line-height:1.8;resize:vertical}.ds-field textarea:hover{border-color:#b7c4d5}.ds-field textarea:focus-visible { outline:2px solid var(--accent, #2459bb);outline-offset:3px; } @media(prefers-reduced-motion:reduce){[class^="ds-"]{transition:none !important}}

.ds-badge{font-size: 12px;
  padding: 3px 8px;
  background: #f1f4f8;
  border: 1px solid #dce3ed;
  border-radius: 4px;
  color: #4f6078;
  overflow-wrap: anywhere;color: #2754a4;
  background: var(--accent-light, #eef4ff);
  border-color: #d2dff5;} @media(prefers-reduced-motion:reduce){[class^="ds-"]{transition:none !important}}

.ds-panel{background: var(--surface, #fff);
  border: 1px solid var(--line, #dce2eb);
  border-radius: 8px;
  padding: 28px;color:var(--text,#202a3b);font-family:-apple-system, BlinkMacSystemFont, 'Segoe UI', 'Microsoft YaHei', sans-serif}.ds-panel h2{font-size:17px;font-weight:600;margin:0 0 12px}.ds-panel p{font-size:14px;line-height:1.9;margin:0} @media(prefers-reduced-motion:reduce){[class^="ds-"]{transition:none !important}}

.ds-rating{background: var(--surface, #fff);
  border: 1px solid #bdc9d9;
  border-radius: 6px;
  padding: 16px 12px;
  display: flex;
  align-items: center;
  flex-direction: column;
  gap: 6px;
  color: var(--text, #202a3b);cursor:pointer}.ds-rating strong{font-size:14px;color:var(--accent,#2459bb)}.ds-rating span{color:var(--muted,#59677a);font-size:12px}.ds-rating:hover:not(:disabled){background: #f1f5fc;
  border-color: #8299bc;}.ds-rating:focus-visible { outline:2px solid var(--accent, #2459bb);outline-offset:3px; }.ds-rating:disabled{opacity:.55;cursor:not-allowed} @media(prefers-reduced-motion:reduce){[class^="ds-"]{transition:none !important}}
